class ApiWorkflowsTool extends ProjectTool2 {
  _temporaryStorage;
  constructor(fileSystem, logger) {
    super(fileSystem, logger);
    this._temporaryStorage = new TemporaryStorageService2(fileSystem);
  }
  async restoreAsync(_options, _cancellationToken) {
    this.logger.info(translate2.t("toolApiworkflow.info.restoreNotRequired"));
    return ToolResult2.success();
  }
  async validateAsync(_options, _cancellationToken) {
    this.logger.info(translate2.t("toolApiworkflow.info.validateNotRequired"));
    return ToolResult2.success();
  }
  async buildAsync(options, _cancellationToken) {
    const tempFolder = await this._temporaryStorage.getTempFolderPath();
    const localBuildFolder = Path2.join(tempFolder, NugetConstants2.OutputFolderName);
    const contentFolder = Path2.join(localBuildFolder, NugetConstants2.ContentFolderName);
    try {
      this.logger.progress(translate2.t("toolApiworkflow.progress.copyingFiles"));
      await this.copyFiles(options.projectPath, contentFolder);
      this.logger.progress(translate2.t("toolApiworkflow.progress.creatingOperateFile"));
      await this.createOperateFile(options, contentFolder);
      this.logger.progress(translate2.t("toolApiworkflow.progress.creatingPackageDescriptor"));
      await this.createPackageDescriptor(localBuildFolder);
      return new ToolResult2(ToolErrorCodes2.Success, translate2.t("toolApiworkflow.success.done"), [localBuildFolder]);
    } catch (error) {
      const errorMessage = error instanceof Error ? error.toString() : String(error);
      this.logger.error(errorMessage);
      return ToolResult2.error(ToolErrorCodes2.InternalError, translate2.t("toolApiworkflow.errors.buildFailed"));
    }
  }
  async packAsync(options, cancellationToken) {
    const buildResult = await this.buildAsync(options, cancellationToken);
    if (!buildResult.isSuccess) {
      return buildResult;
    }
    const localBuildFolder = buildResult.packages[0];
    try {
      this.logger.progress(translate2.t("toolApiworkflow.progress.creatingNugetPackage"));
      const nupkgFileName = `${options.package.id}.${options.package.version}.nupkg`;
      const nupkgPath = Path2.join(options.outputPath, nupkgFileName);
      const packager = new NugetPackager2(this.fileSystem);
      const result = await packager.packAsync(localBuildFolder, options.package, nupkgPath);
      this.logger.progress(translate2.t("toolApiworkflow.progress.packageCreatedSuccessfully"));
      return new ToolResult2(ToolErrorCodes2.Success, translate2.t("toolApiworkflow.success.done"), [result.outputPath]);
    } catch (error) {
      const errorMessage = error instanceof Error ? error.toString() : String(error);
      this.logger.error(errorMessage);
      return ToolResult2.error(ToolErrorCodes2.InternalError, translate2.t("toolApiworkflow.errors.packFailed"));
    }
  }
  async dispose() {
    this.logger.info(translate2.t("toolApiworkflow.info.disposing"));
    try {
      await this._temporaryStorage.cleanup();
    } catch {}
  }
  async copyFiles(sourcePath, destinationPath) {
    await this.fileSystem.mkdir(destinationPath);
    const files = await this.fileSystem.readdir(sourcePath);
    for (const file of files) {
      const sourceFile = Path2.join(sourcePath, file);
      const destinationFile = Path2.join(destinationPath, file);
      const stat = await this.fileSystem.stat(sourceFile);
      if (stat?.isFile()) {
        const content = await this.fileSystem.readFile(sourceFile);
        if (content) {
          await this.fileSystem.writeFile(destinationFile, content);
        }
      }
    }
  }
  async createOperateFile(options, contentFolder) {
    const operateJsonFilePath = Path2.join(contentFolder, NugetConstants2.OperateFileName);
    const exists = await this.fileSystem.exists(operateJsonFilePath);
    if (!exists) {
      await this.createOperateJsonFile(contentFolder, options.projectStorageId ?? "", operateJsonFilePath);
    }
  }
  async createOperateJsonFile(projectPath, projectId, filePath) {
    const entryPointsFilePath = Path2.join(projectPath, NugetConstants2.EntryPointsFileName);
    let mainPath = "";
    const entryPointsExists = await this.fileSystem.exists(entryPointsFilePath);
    if (entryPointsExists) {
      const entryPointsContent = await this.fileSystem.readFile(entryPointsFilePath);
      if (entryPointsContent) {
        try {
          const entryPointsText = new TextDecoder().decode(entryPointsContent);
          const entryPoints = JSON.parse(entryPointsText);
          mainPath = entryPoints.entryPoints?.[0]?.filePath ?? "";
        } catch {}
      }
    }
    const operateFileModel = {
      $schema: "https://cloud.uipath.com/draft/2024-12/operate",
      contentType: ProjectTypes2.Api,
      projectId,
      main: mainPath,
      targetFramework: "Portable",
      runtimeOptions: {
        isAttended: false,
        requiresUserInteraction: false
      }
    };
    const operateJsonString = JSON.stringify(operateFileModel, null, 2);
    await this.fileSystem.writeFile(filePath, operateJsonString);
  }
  async createPackageDescriptor(localBuildFolder) {
    const packageDescriptor = {
      files: {}
    };
    this.addFileIfExists(packageDescriptor, localBuildFolder, NugetConstants2.OperateFileName, NugetConstants2.OperateFileName);
    this.addFileIfExists(packageDescriptor, localBuildFolder, NugetConstants2.EntryPointsFileName, NugetConstants2.EntryPointsFileName);
    this.addFileIfExists(packageDescriptor, localBuildFolder, NugetConstants2.BindingsFileId, NugetConstants2.BindingsV2FileName);
    const packageDescriptorPath = Path2.join(localBuildFolder, NugetConstants2.ContentFolderName, NugetConstants2.PackageDescriptorFileName);
    const packageDescriptorJson = JSON.stringify({
      $schema: "https://cloud.uipath.com/draft/2024-12/package-descriptor",
      ...packageDescriptor
    }, null, 2);
    await this.fileSystem.writeFile(packageDescriptorPath, packageDescriptorJson);
  }
  addFileIfExists(packageDescriptor, _rootFolder, key, fileName) {
    const relativePath = Path2.join(NugetConstants2.ContentFolderName, fileName);
    packageDescriptor.files[key] = relativePath;
  }
}

