    if (securityData.accountKey)
      headers[GATEWAY_HEADERS.ACCOUNT_ID] = securityData.accountKey;
    if (!securityData.gatewayIntegrationEnabled && securityData.tenantKey)
      headers[GATEWAY_HEADERS.TENANT_GLOBAL_ID] = securityData.tenantKey;
    if (securityData.ipRangeBypassSecret)
      headers[GATEWAY_HEADERS.IP_RANGE_BYPASS] = securityData.ipRangeBypassSecret;
