          Result: RESULTS.Failure,
          Message: `Error code: ${result.errorCode} : ${result.message}`,
          Instructions: options.dryRun ? `${result.message}. Resolve the reported issue (resource bindings, variable references, mapping targets, or runtime dependencies) and rerun: uip solution pack <solution-path> --dry-run` : `${result.message}`
